const body = $json.body || $json;
const durationHours = Number(body.durationHours);
const timezone = body.timezone || 'America/Bogota';
const date = String(body.date || '').trim();

if (!date || !/^\d{4}-\d{2}-\d{2}$/.test(date)) {
  return [{ json: { ok: false, statusCode: 400, message: 'date must use YYYY-MM-DD format.' } }];
}

if (![1, 2, 3].includes(durationHours)) {
  return [{ json: { ok: false, statusCode: 400, message: 'durationHours must be 1, 2 or 3.' } }];
}

const midday = new Date(`${date}T12:00:00-05:00`);
const day = midday.getDay();

if (day === 0) {
  return [{ json: { ok: true, slots: [], date, durationHours, timezone, message: 'Sunday is not bookable.' } }];
}

return [{
  json: {
    ok: true,
    date,
    durationHours,
    timezone,
    day,
    calendarTimeMin: `${date}T00:00:00-05:00`,
    calendarTimeMax: day === 6 ? `${date}T14:00:00-05:00` : `${date}T23:59:59-05:00`
  }
}];

const request = $('Validate Request').first().json;
const durationHours = Number(request.durationHours);
const date = request.date;
const day = Number(request.day);

const calendarItems = $('Google Calendar - Busy Events').all().map((item) => item.json);
const bookingItems = $('Postgres - Busy Bookings').all().map((item) => item.json);

function toMs(value) {
  return new Date(value).getTime();
}

function overlaps(startA, endA, startB, endB) {
  return startA < endB && endA > startB;
}

function formatHour(dateValue) {
  return new Intl.DateTimeFormat('es-CO', {
    timeZone: 'America/Bogota',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  }).format(dateValue);
}

const busyIntervals = [];

for (const event of calendarItems) {
  const start = event.start?.dateTime || event.start?.date;
  const end = event.end?.dateTime || event.end?.date;
  if (start && end) {
    busyIntervals.push({ start: toMs(start), end: toMs(end), source: 'calendar' });
  }
}

for (const booking of bookingItems) {
  const start = booking.starts_at || booking.startsAt;
  const end = booking.ends_at || booking.endsAt;
  if (start && end) {
    busyIntervals.push({ start: toMs(start), end: toMs(end), source: 'postgres' });
  }
}

const latestStartHour = day === 6 ? 14 - durationHours : 24 - durationHours;
const slots = [];

for (let hour = 0; hour <= latestStartHour; hour += 1) {
  const startIso = `${date}T${String(hour).padStart(2, '0')}:00:00-05:00`;
  const startDate = new Date(startIso);
  const endDate = new Date(startDate.getTime() + durationHours * 60 * 60 * 1000);
  const startMs = startDate.getTime();
  const endMs = endDate.getTime();

  const isBusy = busyIntervals.some((busy) => overlaps(startMs, endMs, busy.start, busy.end));

  if (!isBusy) {
    slots.push({
      start: startDate.toISOString(),
      end: endDate.toISOString(),
      label: `${formatHour(startDate)} - ${formatHour(endDate)}`,
    });
  }
}

return [{ json: { ok: true, slots } }];
